# TestPlan sheet columns
testplan_cols = [
    'Index', 'SS / Module', 'Feature', 'Test Case Name', 'Test Description',
    'Speed', 'Mode', 'Memory Start Offset', 'Memory End Offset', 'Remarks',
    'Test Steps / Procedure', 'Impacted Registers', 'Validation / Acceptance Criteria',
    'Code Generation'
]

# MetaData sheet columns
metadata_cols = [
    'Index', 'Test Case Name', 'Meta Test Description', 'Meta Test Steps / Procedure',
    'Meta Impacted Registers', 'Meta Validation / Acceptance Criteria',
    'Meta Headers', 'Meta Macros', 'Meta Arrays'
]

wb = Workbook()

# --- TestPlan Sheet ---
ws_tp = wb.active
ws_tp.title = 'TestPlan'

header_font = Font(bold=True, color='FFFFFF', size=11)
header_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
wrap_alignment = Alignment(wrap_text=True, vertical='top')

for col_idx, col_name in enumerate(testplan_cols, 1):
    cell = ws_tp.cell(row=1, column=col_idx, value=col_name)
    cell.font = header_font
    cell.fill = header_fill
    cell.alignment = wrap_alignment

for row_idx, row_data in enumerate(json_data, 2):
    for col_idx, col_name in enumerate(testplan_cols, 1):
        val = row_data.get(col_name, '')
        cell = ws_tp.cell(row=row_idx, column=col_idx, value=val)
        cell.alignment = wrap_alignment

ws_tp.freeze_panes = 'A2'

# Auto-size columns
for col_idx, col_name in enumerate(testplan_cols, 1):
    max_len = len(col_name)
    for row in range(2, len(json_data) + 2):
        val = ws_tp.cell(row=row, column=col_idx).value
        if val:
            max_len = max(max_len, min(len(str(val)), 80))
    adjusted_width = min(max_len + 4, 60)
    ws_tp.column_dimensions[get_column_letter(col_idx)].width = adjusted_width

# --- MetaData Sheet ---
ws_md = wb.create_sheet('MetaData')

for col_idx, col_name in enumerate(metadata_cols, 1):
    cell = ws_md.cell(row=1, column=col_idx, value=col_name)
    cell.font = header_font
    cell.fill = header_fill
    cell.alignment = wrap_alignment

for row_idx, row_data in enumerate(json_data, 2):
    for col_idx, col_name in enumerate(metadata_cols, 1):
        val = row_data.get(col_name, '')
        cell = ws_md.cell(row=row_idx, column=col_idx, value=val)
        cell.alignment = wrap_alignment

ws_md.freeze_panes = 'A2'

for col_idx, col_name in enumerate(metadata_cols, 1):
    max_len = len(col_name)
    for row in range(2, len(json_data) + 2):
        val = ws_md.cell(row=row, column=col_idx).value
        if val:
            max_len = max(max_len, min(len(str(val)), 80))
    adjusted_width = min(max_len + 4, 60)
    ws_md.column_dimensions[get_column_letter(col_idx)].width = adjusted_width

ws_md.sheet_state = 'veryHidden'

wb.save(output_path)
print(f'SUCCESS: Workbook saved to {output_path}')
print(f'Filename: {filename}')
print(f'TestPlan rows: {len(json_data)}')
print(f'MetaData rows: {len(json_data)}')
